const headers = $input.item.json.headers || {};
const rawAuth = headers['authorization'] || headers['Authorization'] || '';
const token = rawAuth.startsWith('Bearer ') ? rawAuth.slice(7) : null;

let role = null;
let userId = null;
let exp = null;
let valid = false;

if (token) {
  const parts = token.split('.');
  if (parts.length === 3) {
    try {
      const payload = JSON.parse(Buffer.from(parts[1], 'base64').toString('utf8'));
      role = payload.role || null;
      userId = payload.userId || null;
      exp = payload.exp || null;
      const knownRoles = ['Sales', 'Manager', 'Instructor', 'SuperAdmin'];
      valid = !!(role && knownRoles.includes(role) && userId && exp && exp * 1000 > Date.now());
    } catch (err) {
      valid = false;
    }
  }
}

const body = $input.item.json.body || {};
const message = (body.message || '').toString().slice(0, 2000);
const sessionId = body.sessionId || `${userId || 'anon'}-${Date.now()}`;

return [{
  json: {
    authHeader: rawAuth, 
    role,
    userId,
    valid,
    message,
    sessionId,
  },
}];

const prev = $('Extract & Decode JWT (best-effort)').item.json;
const redisOut = $json;
const count = redisOut.data ?? redisOut.value ?? redisOut.result ?? Object.values(redisOut)[0];

return [{ json: { ...prev, rateCount: Number(count) || 0 } }];

const data = $('Normalize Rate Counter Value').item.json;
let msg = (data.message || '');

const stripped = msg
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<[^>]+>/g, '')
  .trim();

const lower = stripped.toLowerCase();

const injectionPatterns = [
  /ignore (all|any|the) (previous|prior|above) instructions?/i,
  /reveal (your|the) (system prompt|instructions)/i,
  /you are now (dan|jailbroken|unrestricted)/i,
  /pretend (you|to) (are|be) (an? )?(unrestricted|uncensored)/i,
  /act as (if you have|an) no (restrictions|rules|guardrails)/i,
  /disregard (your|all) (safety|security) (rules|guardrails|instructions)/i,
];

const secretPatterns = [
  /\bjwt_secret\b/i,
  /\bpostgres_password\b/i,
  /\bredis_password\b/i,
  /\bsmtp_pass\b/i,
];

const roleImpersonationPatterns = [
  /pretend (i'?m|i am|you'?re|you are) (a |an )?(manager|superadmin|super admin|instructor|sales)/i,
  /act as (if )?(i'?m|i am) (a |an )?(manager|superadmin|super admin)/i,
  /(grant|give) me (manager|superadmin|super admin|admin) (access|permissions|rights)/i,
  /treat me as (a |an )?(manager|superadmin|super admin)/i,
];

const tooLong = stripped.length > 1500;
const tooShort = stripped.length === 0;
const injectionHit = injectionPatterns.some((re) => re.test(stripped));
const secretHit = secretPatterns.some((re) => re.test(stripped));
const roleHit = roleImpersonationPatterns.some((re) => re.test(stripped));

const blocked = tooLong || tooShort || injectionHit || secretHit || roleHit;
let reason = null;
if (tooShort) reason = 'empty_message';
else if (tooLong) reason = 'message_too_long';
else if (injectionHit) reason = 'blocked_injection_pattern';
else if (secretHit) reason = 'blocked_secret_reference';
else if (roleHit) reason = 'blocked_role_impersonation_attempt';

return [{ json: { ...data, message: stripped, blocked, blockReason: reason } }];

const original = $('Input Guardrail (verify BEFORE LLM)').item.json;
const alreadyGreeted = $json.alreadyGreeted;
const isFirstMessage = !alreadyGreeted;
return [{ json: { ...original, isFirstMessage } }];

const ctx = $('Input Guardrail (verify BEFORE LLM)').item.json;
let reply = String($json.output || $json.text || $json.reply || '');

const leakPatterns = [
  /jwt_secret/i,
  /postgres_password/i,
  /redis_password/i,
  /smtp_pass/i,
  /bearer [a-z0-9\-_.]{20,}/i,
  /you are the training platform assistant for an? (sales|manager|instructor|superadmin) user/i,
];

const adminOnlyVocabulary = [
  /\baudit_log\b/i,
  /\bpassword_hash\b/i,
  /deactivate(d)? (a |the )?user/i,
  /\bsuperadmin (role|access|privileges)\b/i,
];
const privilegeLeakHit = ctx.role !== 'SuperAdmin' && adminOnlyVocabulary.some((re) => re.test(reply));

let redacted = false;
let redactReason = null;

if (leakPatterns.some((re) => re.test(reply))) {
  redacted = true;
  redactReason = 'leak_pattern';
} else if (privilegeLeakHit) {
  redacted = true;
  redactReason = 'privilege_leak_for_role';
}

if (redacted) {
  reply = "I can't share that. Is there something else about trainings or sessions I can help with?";
}

const imageMatch = reply.match(/data:image\/(png|jpe?g|gif|webp);base64,[A-Za-z0-9+/=]+/i);
let image = null;
if (imageMatch && !redacted) {
  image = { dataUrl: imageMatch[0] };
  reply = (reply.slice(0, imageMatch.index) + reply.slice(imageMatch.index + imageMatch[0].length))
    .replace(/!\[[^\]]*\]\(\s*\)/g, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}
const containsImage = !!image;

const MAX_REPLY_CHARS = 4000;
if (reply.length > MAX_REPLY_CHARS) {
  reply = reply.slice(0, MAX_REPLY_CHARS) + '\n\n[Response truncated - ask a more specific question for full detail.]';
}

const dynamicHints = /(session|report|client|approved|created|instructor profile|user|audit|deactivat)/i;
const cacheable = !redacted && !containsImage && !dynamicHints.test(ctx.message);

return [{
  json: {
    reply,
    role: ctx.role,
    message: ctx.message,
    cacheable,
    image,
  },
}];

const ctx = $('Code: Determine First Message').item.json;
return [{
  json: {
    message: ctx.message,
    role: ctx.role,
    userId: ctx.userId,
    authHeader: ctx.authHeader,
    isFirstMessage: ctx.isFirstMessage,
    sessionId: ctx.sessionId,
  },
}];
